<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {api,openProtected} from './api'
import './forum.css'
type Step={point_id:number;name:string;purpose:string;mastery:string|null;sample_size:number;evidence_note:string;explanation:string;prerequisite_ids:number[];evidence:any[];materials:any[];cited_refs:string[]}
type Plan={id:number;status:string;revision:number;steps:Step[];selected_ids:number[];schedule:any;stale:boolean;error:string;window:{start:string;end:string};reminders:any[]}
const props=defineProps<{courseId:number;isTeacher:boolean}>()
const plans=ref<Plan[]>([]),next=ref<number|null>(null),busy=ref(false),loading=ref(true),error=ref(''),notice=ref(''),selected=ref<Record<number,number[]>>({}),schedules=ref<Record<number,any>>({}),intervals=ref<Record<number,string>>({})
const start=ref(new Date(Date.now()-90*86400000).toISOString().slice(0,10)),end=ref(new Date(Date.now()+86400000).toISOString().slice(0,10))
const labels:Record<string,string>={queued:'排队中',running:'生成中',awaiting_confirmation:'待本人确认',active:'已启用',cancelled:'已取消',failed:'生成失败',scheduled:'待复习',completed:'已完成'}
function defaults(){return {timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Shanghai',start_date:new Date(Date.now()+2*86400000).toISOString().slice(0,10),local_time:'18:00',offset_days:[0,1,3,7]}}
function initialize(p:Plan){selected.value[p.id]=p.selected_ids.length?[...p.selected_ids]:p.steps.map(s=>s.point_id);schedules.value[p.id]=Object.keys(p.schedule).length?{...p.schedule}:defaults();intervals.value[p.id]=schedules.value[p.id].offset_days.join(',')}
async function run(action:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(page=1){const d=await api<{items:Plan[];next_page:number|null}>(`courses/${props.courseId}/review-plans/?page=${page}`);plans.value=page===1?d.items:[...plans.value,...d.items];next.value=d.next_page;for(const p of d.items)initialize(p)}
async function create(){await run(async()=>{const p=await api<Plan>(`courses/${props.courseId}/review-plans/`,'POST',{start:new Date(start.value+'T00:00:00Z').toISOString(),end:new Date(end.value+'T00:00:00Z').toISOString()});plans.value.unshift(p);initialize(p);notice.value='任务已保存。稍后刷新查看生成结果；确认前不会创建提醒。'})}
function choose(p:Plan,id:number,checked:boolean){const set=new Set(selected.value[p.id]);if(checked){const add=(n:number)=>{if(set.has(n))return;set.add(n);for(const pre of p.steps.find(s=>s.point_id===n)?.prerequisite_ids||[])add(pre)};add(id)}else{set.delete(id);let changed=true;while(changed){changed=false;for(const s of p.steps)if(set.has(s.point_id)&&s.prerequisite_ids.some(n=>!set.has(n))){set.delete(s.point_id);changed=true}}}selected.value[p.id]=[...set]}
async function act(p:Plan,action:string){await run(async()=>{const offset_days=intervals.value[p.id].split(/[,，]/).map(v=>v.trim()).map(v=>v===''?NaN:Number(v));const updated=await api<Plan>(`review-plans/${p.id}/action/`,'POST',{action,expected_revision:p.revision,point_ids:selected.value[p.id],schedule:{...schedules.value[p.id],offset_days}});plans.value=plans.value.map(old=>old.id===p.id?updated:old);initialize(updated);notice.value=action==='cancel'?'计划及未完成提醒已取消':'计划已保存，提醒保存在本站待办中。'})}
async function reminder(p:Plan,id:number,action:string){await run(async()=>{await api(`review-reminders/${id}/`,'POST',{action});const updated=await api<Plan>(`review-plans/${p.id}/`);plans.value=plans.value.map(old=>old.id===p.id?updated:old);initialize(updated)})}
function date(value:string){return new Date(value).toLocaleString()}
onMounted(async()=>{if(!props.isTeacher)await run(()=>load());loading.value=false})
</script>
<template>
<section class="forum-workspace review-workspace"><div class="section-head"><div><h2>复习路径与提醒</h2><p>按正式先修关系组织复习，确认后生成持久化站内待办。</p></div><button v-if="!isTeacher" class="secondary" :disabled="busy" @click="run(()=>load())">刷新计划</button></div>
<p v-if="isTeacher">这是学生个人功能。学生依据自己的已公开正式评分和本课程图谱生成路径；教师可在知识图谱中维护先修关系与资料。</p>
<template v-else><p v-if="loading" role="status">正在加载复习计划…</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<form class="forum-card review-settings" @submit.prevent="create"><label>分析开始日期（UTC）<input v-model="start" type="date" required></label><label>结束日期（UTC，不含当日）<input v-model="end" type="date" required></label><button class="primary" :disabled="busy||plans.some(p=>['queued','running'].includes(p.status))">生成个人复习建议</button></form>
<p v-if="!loading&&!plans.length&&!error">尚无复习计划。先由教师建立知识图谱，再生成建议。</p>
<article v-for="p in plans" :key="p.id" class="forum-card"><h3>复习计划 #{{p.id}} · {{labels[p.status]||p.status}}</h3><p>评分窗口 {{date(p.window.start)}} 至 {{date(p.window.end)}}（结束不含）。仅使用本人已公开正式评分。</p><p v-if="p.stale" role="alert" class="error">评分、图谱或资料已变化，本计划提醒暂停使用，请重新生成。旧说明与依据已隐藏，避免继续展示撤回的内容。</p><p v-if="p.error" role="alert" class="error">{{p.error}}</p><p v-if="['queued','running'].includes(p.status)">建议正在后台生成，可刷新查看，也可取消任务。确认前不会生成提醒。</p>
<ol class="review-steps"><li v-for="s in p.steps" :key="s.point_id"><label><input type="checkbox" :checked="selected[p.id]?.includes(s.point_id)" :disabled="busy||p.stale||!['awaiting_confirmation','active'].includes(p.status)" @change="choose(p,s.point_id,($event.target as HTMLInputElement).checked)"><strong>{{s.name}}</strong></label><p>{{s.mastery===null?'掌握度未知':`评分得分率 ${(Number(s.mastery)*100).toFixed(1)}%`}} · {{s.sample_size}} 道有效题 · {{s.purpose==='weakness'?'待巩固':s.purpose==='prerequisite'?'先修步骤':'一般复习'}}</p><p>{{s.evidence_note}}</p><p class="review-explanation">{{s.explanation}}</p><details><summary>查看选择依据与资料</summary><p v-for="e in s.evidence" :key="e.attempt_id+'-'+e.question_id">本人答卷 #{{e.attempt_id}} · 题 #{{e.question_id}} · {{e.score}}/{{e.maximum}} · 评分 v{{e.grade_revision}}</p><p v-if="!s.evidence.length">暂无有效评分证据，不据此判断薄弱。</p><div v-for="m in s.materials" :key="m.id"><button class="secondary" :disabled="busy||p.stale" @click="run(()=>openProtected(m.preview_url))">预览：{{m.title}}</button><p v-for="source in m.sources" :key="source.chunk_id">片段 #{{source.chunk_id}}：{{source.excerpt}}</p></div><p v-if="!s.materials.length">暂无教师关联资料。</p><p>说明所用引用：{{s.cited_refs?.join('、')||'无资料引用，仅一般复习建议'}}</p></details></li></ol>
<form v-if="['awaiting_confirmation','active'].includes(p.status)&&!p.stale" class="review-settings" @submit.prevent="act(p,p.status==='active'?'reschedule':'confirm')"><label>时区<input v-model="schedules[p.id].timezone" required placeholder="Asia/Shanghai"></label><label>开始日期<input v-model="schedules[p.id].start_date" type="date" required></label><label>当地提醒时间<input v-model="schedules[p.id].local_time" type="time" required></label><label>距开始日期的天数<input v-model="intervals[p.id]" required placeholder="0,1,3,7"></label><p>按上述时区及间隔，为每个所选知识点创建站内待办。勾选后学知识会自动保留先修步骤；取消先修会同时取消依赖步骤。调整后旧的未完成提醒将取消。</p><button class="primary" :disabled="busy||!selected[p.id]?.length">{{p.status==='active'?'确认调整提醒':'确认步骤并创建提醒'}}</button></form>
<h4 v-if="p.reminders.length">站内复习待办</h4><p v-if="p.reminders.length>=500">展示最新修订优先的前500条提醒，更多历史保留在数据库。</p><ul class="review-reminders"><li v-for="r in p.reminders" :key="r.id"><span>{{p.steps.find(s=>s.point_id===r.point_id)?.name||'#'+r.point_id}} · {{date(r.due_at)}} · {{labels[r.state]||r.state}}{{p.stale&&r.state==='scheduled'?'（依据变化，暂停）':r.due?'（已到期）':''}}</span><button v-if="r.actionable" class="secondary" :disabled="busy" @click="reminder(p,r.id,'complete')">标记完成</button><button v-if="r.state==='scheduled'&&p.status==='active'" class="secondary" :disabled="busy" @click="reminder(p,r.id,'cancel')">取消此提醒</button></li></ul><button v-if="p.status!=='cancelled'" class="secondary" :disabled="busy" @click="act(p,'cancel')">取消此计划及未完成提醒</button></article>
<button v-if="next" class="secondary" :disabled="busy" @click="run(()=>load(next!))">加载更早计划</button></template></section>
</template>
<style scoped>
.review-settings{display:flex;flex-wrap:wrap;gap:14px;align-items:end;margin:16px 0}.review-settings label{display:grid;gap:6px;flex:1 1 170px;min-width:0}.review-settings input{width:100%;min-width:0}.review-settings p{flex-basis:100%}.review-steps{padding-left:24px}.review-steps>li{padding:14px 0;border-bottom:1px solid #ddd}.review-steps input[type=checkbox]{width:auto;margin-right:8px}.review-explanation{white-space:pre-wrap}.review-reminders{padding-left:20px}.review-reminders li{margin:12px 0;display:flex;flex-wrap:wrap;gap:8px;align-items:center}.review-reminders span{flex:1 1 250px}.review-workspace{min-width:0;overflow-wrap:anywhere}
</style>
